window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f1c4bf15d7d9920c"]={"versions": [{"id": "FIG-f1c4bf15d7d9920c", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Werkzeug-Übersichtsdiagramm zur Darstellung der Datenbasis, Metamodellstrukturen und Generierungs- bzw. Spezifikationsbeziehungen innerhalb der AUTOSAR-Entwicklungsumgebung. Der Kontext umfasst das zentrale MetaModel (gegliedert in Methodology Model, Template Metamodel, MSR und Description Model) sowie die Ableitung von Spezifikationsdokumenten (PDF-Format) und Austauschformaten (XML-Schema, XML-Parameterbeschreibungen).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten und Komponenten:</p>\n<ul class=\"fig-list\">\n<li><strong>Zentraler Speicher / MetaModel (EAP-Format)</strong>:</li>\n<li><em>Methodology Model</em>: Enthält <code>Methodology</code>.</li>\n<li><em>Template Metamodel</em>: Enthält <code>Software Component Template</code>, <code>ECU Resource Template</code>, <code>System Template</code>, <code>ECU Configuration Template</code>, <code>Basic Software Module Template</code>, <code>Generic Structure Template</code>.</li>\n<li><em>MSR</em>: Zwischengelagertes Daten-/Strukturmodell.</li>\n<li><em>Description Model</em>: Enthält <code>ECU Configuration Parameter Description</code>.</li>\n<li><strong>Eingangs- und Regelwerke</strong>:</li>\n<li><code>Template UML Profile and Modeling Guide</code> (PDF-Format, steuert Modellierung via „how to“).</li>\n<li><code>Model Persistence Rules for XML</code> (PDF-Format, steuert automatische Generierung via „how to auto-generate“).</li>\n<li><code>Basic Software SWS's Chapter 10</code> (DOC-Format, liefert manuellen Input via „manual input“ in das Description Model).</li>\n<li><strong>Zieldokumente / Spezifikationen (PDF-Format)</strong>:</li>\n<li><code>Methodology Specification</code> (referenziert <code>Methodology Model</code>).</li>\n<li><em>AUTOSAR Template Specifications</em>: <code>Software Component Template Specification</code>, <code>ECU Resource Template Specification</code>, <code>System Template Specification</code>, <code>ECU Configuration Template Specification</code>, <code>BSW Module Template Specification</code>, <code>Common Modeling Pattern Template Specification</code> (referenziert über Diagramme, Kommentare etc. aus dem <code>Template Metamodel</code>).</li>\n<li><code>ECU Configuration Param. Description Specification</code> (referenziert <code>Description Model</code>).</li>\n<li><strong>Generierte Ausgabeartefakte (XML-Format)</strong>:</li>\n<li><code>XML Schema</code> (automatisch generiert aus <code>Template Metamodel</code>).</li>\n<li><code>ECU Config Parameter Description</code> (automatisch generiert aus <code>Description Model</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Beziehungsdarstellung mit transformatorischen Prozessflüssen:</p>\n<ul class=\"fig-list\">\n<li>Vorgaben aus dem <code>Template UML Profile and Modeling Guide</code> wirken auf das <code>Template Metamodel</code>.</li>\n<li>Das Kapitel 10 der BSW-Spezifikationen (<code>Basic Software SWS's Chapter 10</code>) fließt per manuellem Input in das <code>Description Model</code> ein.</li>\n<li>Gesteuert durch die <code>Model Persistence Rules for XML</code> wird aus dem <code>Template Metamodel</code> automatisiert das <code>XML Schema</code> generiert.</li>\n<li>Aus dem <code>Description Model</code> wird automatisiert die <code>ECU Config Parameter Description</code> erzeugt.</li>\n<li>Die Spezifikationsdokumente (Methodology, Templates, Parameterbeschreibung) referenzieren Modellelemente, Diagramme und Kommentare der jeweiligen Schichten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als übergeordnete Orientierung über den Zusammenhang zwischen den internen AUTOSAR-UML-Modellen (Enterprise Architect / EAP) und den normativ verbindlichen Arbeitsergebnissen. Für Entwickler verdeutlicht es, dass die XML-Schemata und Parameterbeschreibungen direkt aus den formalen Metamodellen abgeleitet werden, während die Textspezifikationen erklärende und normative Beschreibungen zu den jeweiligen Metamodellpaketen bereitstellen.</p>"}, {"id": "FIG-26f2a329826bb219", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paket- und Artefakt-Diagramm zur Darstellung der Struktur eines Enterprise-Architect-Repositories (<code>This Enterprise Architect repository</code>) und dessen Beziehungen zu generierten Spezifikationsdokumenten und Schemadateien im AUTOSAR-Umfeld. Es veranschaulicht die Metamodell-Ebenen M2 und M1 sowie die Generierungsabhängigkeiten zu PDF- und XML-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Pakete und Artefakte:</p>\n<ul class=\"fig-list\">\n<li><strong>This Enterprise Architect repository</strong>:</li>\n<li>Paket <code>Methodology</code> (Stereotyp/Kontext <code>(from M2)</code>): Enthält Unterpakete <code>+ WorkProducts</code>, <code>+ Tools</code>, <code>+ ViewsAndActivities</code>, <code>+ Connection of BMTs</code>.</li>\n<li>Paket <code>M2 Metamodel</code>:</li>\n<li>Paket <code>AUTOSAR Templates</code> <code>(from M2)</code> mit Unterpaketen <code>+ GenericStructure</code>, <code>+ ECUResourceTemplate</code>, <code>+ SWComponentTemplate</code>, <code>+ SystemTemplate</code>, <code>+ ECUCParameterDefTemplate</code>, <code>+ ECUCDescriptionTemplate</code>, <code>+ BswModuleTemplate</code>.</li>\n<li>Paket <code>MSR</code> <code>(from M2)</code> mit Unterpaketen <code>+ MSR</code>, <code>+ ContentModel</code>, <code>+ Msrsw</code>, <code>+ ArchitecturalView</code>, <code>+ DataDictionary</code>, <code>+ DynamicView</code>, <code>+ ConfigurationOnM1</code>, <code>+ Documentation</code>, <code>+ Collection</code>, <code>+ CalibrationData</code>, <code>+ CalibrationSystem</code>, <code>+ Cpu</code>, <code>+ AsamHdo</code>, <code>+ AdminProjectData</code>, <code>+ GeneralMDS</code>, <code>+ MsrTrCap</code>.</li>\n<li>Paket <code>AUTOSAR Descriptions</code> <code>(from M1)</code> mit Unterpaket <code>+ ECUCParameterDefinitions</code>.</li>\n<li><strong>Generierte / teilweise generierte Artefakte</strong>:</li>\n<li><code>Methodology Specification :.pdf</code> (teilgeneriert aus <code>Methodology</code>).</li>\n<li>Rahmen <code>Template Specifications</code> mit PDF-Artefakten: <code>Common Modeling Patterns Specification :.pdf</code>, <code>ECU Resource Template Specification :.pdf</code>, <code>Software Component Template Specification :.pdf</code>, <code>System Template Specification :.pdf</code>, <code>ECU Configuration Template Specification :.pdf</code>, <code>BSW Module Description Template Specification :.pdf</code> (teilgeneriert aus <code>AUTOSAR Templates</code> / <code>MSR</code>).</li>\n<li><code>ECU Configuration Parameter Description :.pdf</code> (teilgeneriert aus <code>AUTOSAR Descriptions</code>).</li>\n<li><code>XML Schema :.xml</code> (teilgeneriert aus <code>MSR</code> / M2-Metamodell).</li>\n<li><code>ECU Configuration Parameter Description :.xml</code> (vollständig generiert <code>«generated»</code> aus <code>AUTOSAR Descriptions</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell für Artefaktgenerierung:</p>\n<ul class=\"fig-list\">\n<li>Gerichtete Abhängigkeiten mit Stereotyp <code>«partly generated»</code> führen von den Metamodellpaketen (<code>Methodology</code>, <code>AUTOSAR Templates</code>, <code>MSR</code>, <code>AUTOSAR Descriptions</code>) zu den entsprechenden PDF-Spezifikationen sowie zum <code>XML Schema :.xml</code>.</li>\n<li>Eine gerichtete Abhängigkeit mit Stereotyp <code>«generated»</code> führt vom Paket <code>AUTOSAR Descriptions</code> (M1) zum Dateiartefakt <code>ECU Configuration Parameter Description :.xml</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die methodische Trennung zwischen M2-Metamodellierung und M1-Beschreibungsdaten innerhalb des zentralen Repositorys. Für Entwickler und Werkzeughersteller ist verbindlich nachvollziehbar, welche Spezifikationen und Schemata automatisiert oder teilautomatisiert aus den jeweiligen UML-Paketen abgeleitet werden, insbesondere die duale Ableitung der ECU-Konfigurationsparameter in PDF- und XML-Repräsentationen.</p>"}, {"id": "FIG-f50dda6588b49620", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Paket- und Artefakt-Diagramm zur Darstellung der Struktur eines Enterprise-Architect-Repositories (<code>This Enterprise Architect repository</code>) und dessen Beziehungen zu generierten Spezifikationsdokumenten und Schemadateien im AUTOSAR-Umfeld. Es veranschaulicht die Metamodell-Ebenen M2 und M1 sowie die Generierungsabhängigkeiten zu PDF- und XML-Artefakten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Pakete und Artefakte:</p>\n<ul class=\"fig-list\">\n<li><strong>This Enterprise Architect repository</strong>:</li>\n<li>Paket <code>Methodology</code> (Stereotyp/Kontext <code>(from M2)</code>): Enthält Unterpakete <code>+ WorkProducts</code>, <code>+ Tools</code>, <code>+ ViewsAndActivities</code>, <code>+ Connection of BMTs</code>.</li>\n<li>Paket <code>M2 Metamodel</code>:</li>\n<li>Paket <code>AUTOSAR Templates</code> <code>(from M2)</code> mit Unterpaketen <code>+ GenericStructure</code>, <code>+ ECUResourceTemplate</code>, <code>+ SWComponentTemplate</code>, <code>+ SystemTemplate</code>, <code>+ ECUCParameterDefTemplate</code>, <code>+ ECUCDescriptionTemplate</code>, <code>+ BswModuleTemplate</code>.</li>\n<li>Paket <code>MSR</code> <code>(from M2)</code> mit Unterpaketen <code>+ MSR</code>, <code>+ ContentModel</code>, <code>+ Msrsw</code>, <code>+ ArchitecturalView</code>, <code>+ DataDictionary</code>, <code>+ DynamicView</code>, <code>+ ConfigurationOnM1</code>, <code>+ Documentation</code>, <code>+ Collection</code>, <code>+ CalibrationData</code>, <code>+ CalibrationSystem</code>, <code>+ Cpu</code>, <code>+ AsamHdo</code>, <code>+ AdminProjectData</code>, <code>+ GeneralMDS</code>, <code>+ MsrTrCap</code>.</li>\n<li>Paket <code>AUTOSAR Descriptions</code> <code>(from M1)</code> mit Unterpaket <code>+ ECUCParameterDefinitions</code>.</li>\n<li><strong>Generierte / teilweise generierte Artefakte</strong>:</li>\n<li><code>Methodology Specification :.pdf</code> (teilgeneriert aus <code>Methodology</code>).</li>\n<li>Rahmen <code>Template Specifications</code> mit PDF-Artefakten: <code>Common Modeling Patterns Specification :.pdf</code>, <code>ECU Resource Template Specification :.pdf</code>, <code>Software Component Template Specification :.pdf</code>, <code>System Template Specification :.pdf</code>, <code>ECU Configuration Template Specification :.pdf</code>, <code>BSW Module Description Template Specification :.pdf</code> (teilgeneriert aus <code>AUTOSAR Templates</code> / <code>MSR</code>).</li>\n<li><code>ECU Configuration Parameter Description :.pdf</code> (teilgeneriert aus <code>AUTOSAR Descriptions</code>).</li>\n<li><code>XML Schema :.xml</code> (teilgeneriert aus <code>MSR</code> / M2-Metamodell).</li>\n<li><code>ECU Configuration Parameter Description :.xml</code> (vollständig generiert <code>«generated»</code> aus <code>AUTOSAR Descriptions</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell für Artefaktgenerierung:</p>\n<ul class=\"fig-list\">\n<li>Gerichtete Abhängigkeiten mit Stereotyp <code>«partly generated»</code> führen von den Metamodellpaketen (<code>Methodology</code>, <code>AUTOSAR Templates</code>, <code>MSR</code>, <code>AUTOSAR Descriptions</code>) zu den entsprechenden PDF-Spezifikationen sowie zum <code>XML Schema :.xml</code>.</li>\n<li>Eine gerichtete Abhängigkeit mit Stereotyp <code>«generated»</code> führt vom Paket <code>AUTOSAR Descriptions</code> (M1) zum Dateiartefakt <code>ECU Configuration Parameter Description :.xml</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die methodische Trennung zwischen M2-Metamodellierung und M1-Beschreibungsdaten innerhalb des zentralen Repositorys. Für Entwickler und Werkzeughersteller ist verbindlich nachvollziehbar, welche Spezifikationen und Schemata automatisiert oder teilautomatisiert aus den jeweiligen UML-Paketen abgeleitet werden, insbesondere die duale Ableitung der ECU-Konfigurationsparameter in PDF- und XML-Repräsentationen.</p>"}], "trans": [{"from": "FIG-f1c4bf15d7d9920c", "to": "FIG-26f2a329826bb219", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Umstellung der gesamten Architektur- und Werkzeugrepräsentation von einer zylindrischen Datenbankschichtung auf ein Enterprise-Architect-UML-Repository (<code>This Enterprise Architect repository</code>).</li>\n<li>Explizite Gliederung der Metamodell-Ebenen nach MOF/M2 (<code>M2 Metamodel</code>) und Beschreibungs-Instanzen nach M1 (<code>(from M1)</code>).</li>\n<li>Strukturierung der Inhalte in UML-Pakete mit detaillierten Unterpaketen:</li>\n<li><code>Methodology</code> (M2) mit Unterpaketen <code>WorkProducts</code>, <code>Tools</code>, <code>ViewsAndActivities</code>, <code>Connection of BMTs</code>.</li>\n<li><code>AUTOSAR Templates</code> (M2) mit Unterpaketen <code>GenericStructure</code>, <code>ECUResourceTemplate</code>, <code>SWComponentTemplate</code>, <code>SystemTemplate</code>, <code>ECUCParameterDefTemplate</code>, <code>ECUCDescriptionTemplate</code>, <code>BswModuleTemplate</code>.</li>\n<li><code>MSR</code> (M2) mit 14 Unterpaketen (<code>MSR</code>, <code>ContentModel</code>, <code>Msrsw</code>, <code>ArchitecturalView</code>, <code>DataDictionary</code>, <code>DynamicView</code>, <code>ConfigurationOnM1</code>, <code>Documentation</code>, <code>Collection</code>, <code>CalibrationData</code>, <code>CalibrationSystem</code>, <code>Cpu</code>, <code>AsamHdo</code>, <code>AdminProjectData</code>, <code>GeneralMDS</code>, <code>MsrTrCap</code>).</li>\n<li><code>AUTOSAR Descriptions</code> (M1) mit Paket <code>ECUCParameterDefinitions</code>.</li>\n<li>Änderung der Generierungsbeziehungen:</li>\n<li>Die Generierung der PDF-Spezifikationen ist als UML-Abhängigkeit mit Stereotyp <code>«partly generated»</code> modelliert, ausgehend von <code>Methodology</code>, den <code>AUTOSAR Templates</code> / <code>MSR</code> sowie <code>AUTOSAR Descriptions</code>.</li>\n<li>Die Artefakte sind als Artefakt-Klassen mit Dateiendung typisiert (z. B. <code>.pdf</code>, <code>.xml</code>).</li>\n<li><code>ECU Configuration Parameter Description</code> wird nun sowohl als <code>.xml</code> (<code>«generated»</code>) als auch als <code>.pdf</code> (<code>«partly generated»</code>) erzeugt.</li>\n<li>Die Generierung des <code>XML Schema :.xml</code> basiert nun direkt auf dem Paket <code>MSR</code> bzw. M2-Metamodell (<code>«partly generated»</code>).</li>\n<li>Entfall der Dokumente/Eingabequellen <code>Template UML Profile and Modeling Guide</code>, <code>Model Persistence Rules for XML</code> und <code>Basic Software SWS's Chapter 10</code> sowie der Formats-Legende (EAP, XML, PDF, DOC).</li>\n</ul>"}, {"from": "FIG-26f2a329826bb219", "to": "FIG-f50dda6588b49620", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
